using namespace std;

class Solution {
public:
    int getMaximumDistance(vector<int>& location, int k) {
        vector<int> loc = location;
        sort(loc.begin(), loc.end());
        int n = loc.size();
        if (k >= n) return 0;
        auto can = [&](int d) {
            int clusters = 1, a = loc[0];
            for (int x : loc) {
                if (x - a > 2 * d) { clusters++; a = x; if (clusters > k) return false; }
            }
            return true;
        };
        int lo = 0, hi = (loc.back() - loc.front() + 1) / 2 + 1;
        while (lo < hi) { int mid = (lo + hi) / 2; if (can(mid)) hi = mid; else lo = mid + 1; }
        return lo;
    }
};
